def shapes(g):
    cs=components(g)
    yellow=[c for c in cs if any(g[r][c0]==4 for r,c0 in c)]
    orange=[c for c in cs if all(g[r][c0]==7 for r,c0 in c)]
    groups=[set(c) for c in yellow]
    for oc in orange:
        idx=min(range(len(groups)),key=lambda i:min(abs(r-r2)+abs(c-c2) for r,c in oc for r2,c2 in groups[i]))
        groups[idx]|=oc
    return groups

def transform(g):
    A,B=shapes(g)
